const COLS=25, ROWS=15, CELL=40;
// The pond is blocked. Hill and ramp/platform cells are traversable automatically.
function blocked(x,y,zone='grounds'){if(zone==='hq')return hqBlocked(x,y);if(zone==='farm')return farmBlocked(x,y);return x>=13&&x<=16&&y>=4&&y<=7;}
function cellAt(x,y){return [Math.max(0,Math.min(COLS-1,Math.floor(x/CELL))),Math.max(0,Math.min(ROWS-1,Math.floor(y/CELL)))];}
function pathfind(from,to,zone='grounds'){const start=cellAt(...from),goal=cellAt(...to);if(blocked(...goal,zone))return [];const key=p=>p.join(',');const queue=[start],parents=new Map([[key(start),null]]);for(let i=0;i<queue.length;i++){const p=queue[i];if(key(p)===key(goal)){const out=[];let c=p;while(parents.get(key(c))!==null){out.push([c[0]*CELL+20,c[1]*CELL+20]);c=parents.get(key(c));}return out.reverse();}for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const n=[p[0]+dx,p[1]+dy];if(n[0]<0||n[1]<0||n[0]>=COLS||n[1]>=ROWS||blocked(...n,zone)||parents.has(key(n)))continue;parents.set(key(n),p);queue.push(n);}}return [];}

// Assets are optional: geometric presentation remains usable if an asset fails.
class AssetLoader {
  constructor(){this.images=new Map();}
  async load(manifest){await Promise.all(Object.entries(manifest).map(([key,url])=>new Promise(resolve=>{const img=new Image();img.onload=()=>{this.images.set(key,img);resolve()};img.onerror=()=>resolve();img.src=url})));return this;}
  get(key){return this.images.get(key);}
}
class SceneManager {
  constructor(){this.current='welcome';}
  enter(name){if(!['welcome','grounds'].includes(name))throw new Error('Unknown scene');this.current=name;}
}
class CharacterRegistry {
  constructor(roster){this.roster=roster;this.active=roster[0];this.visuals=new Map();}
  register(name,visual){if(!this.roster.some(r=>r[0]===name))throw new Error('Unknown canonical character');this.visuals.set(name,visual);}
  select(name){if(!this.visuals.has(name))return false;this.active=this.roster.find(r=>r[0]===name);return true;}
}

