function getJournalEntries(section,found,visited,objects,materials,farm={}){
 const farmState=normalizeFarm(farm);
 const seen=new Set(visited);
 // Older browser saves only recorded discoveries. Preserve that history.
 for(const id of found)if(objects.some(o=>o.id===id))seen.add(id);
 if(materials.some(m=>found.has(m.id)))seen.add('dig');
 if(section==='experiments')return farmState.experiments.map(id=>({id:'experiment-'+id,title:farmExperiments[id][0],summary:farmExperiments[id][0],fact:'I can repeat this model and try a different choice.',icon:'🔬',target:farmExperiments[id][1]})); // Observation visits are not completed experiments.
 if(section==='found'||section==='minerals')return [...objects,...materials].filter(o=>found.has(o.id)&&(section!=='minerals'||['quartz','iron'].includes(o.id))).map(o=>({id:o.id,title:o.name,icon:o.icon,summary:section==='minerals'?'I found '+o.name.toLowerCase()+'.':'I discovered '+o.name.toLowerCase()+'.',fact:({quartz:'Quartz is a mineral with crystal faces.',iron:'Some iron-bearing minerals are attracted to magnets.',fossil:'A fossil is a trace or remain of ancient life.'})[o.id]||journalActivities[o.id]?.[1]||o.text,target:materials.includes(o)?'dig':o.id})).concat(section==='found'?farmPlants.filter(p=>farmState.seeds.includes(p.id)).map(p=>({id:'seed-'+p.id,title:p.name+' seed',icon:p.icon,summary:'I collected a '+p.name.toLowerCase()+' sample seed.',fact:p.fact,target:'farm-bank'})):[]);
 return objects.filter(o=>seen.has(o.id)&&(section!=='adventures'||(['home','plant','rock','crystal','bridge'].includes(o.id)||o.zone==='hq'||o.zone==='farm'))).map(o=>({id:o.id,title:journalActivities[o.id][0],icon:o.icon,summary:journalActivities[o.id][0],fact:journalActivities[o.id][1],target:o.id}));
}

